begin
  with legacy_dates as (
    select key as box_nome,value::date as data_oferta
    from jsonb_each_text(v_dates)
  )
  update clube_novo.box_contexto_contratacao_v1 x
  set data_oferta=d.data_oferta
  from legacy_dates d
  where x.box_nome=d.box_nome
    and x.estado_box='finalizada'
    and x.oferta_fonte=v_source;
  get diagnostics v_updated=row_count;

  select count(*) into v_matching
  from clube_novo.box_contexto_contratacao_v1 x
  join jsonb_each_text(v_dates) d
    on d.key=x.box_nome and d.value::date=x.data_oferta
  where x.estado_box='finalizada' and x.oferta_fonte=v_source;

  if v_updated<>1023 or v_matching<>1023 then
    raise exception 'datas do legado divergentes: % atualizadas e % conferidas',v_updated,v_matching;
  end if;
end
$copy_dates$;

comment on column clube_novo.box_acervo_legado_v1.campos_copiados is
  'Escopo fechado da cópia: nome da box, card_id dos participantes e data da box.';
